<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Footer Settings | Indus Resort</title><link href="https://cdn.jsdelivr.net/npm/remixicon@3.5.0/fonts/remixicon.css" rel="stylesheet"><link rel="stylesheet" href="{{ asset('css/admin.css') }}"><style>.footer-editor{max-width:850px;padding:30px}.footer-editor h2{margin:0}.muted{color:#718096}.footer-editor textarea{width:100%;box-sizing:border-box;border:1px solid #d7e1dc;border-radius:9px;padding:13px;font:inherit;resize:vertical}.social-fields{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:12px 0 22px}.social-fields label{display:grid;gap:6px;font-weight:700;color:#24433a}.social-fields input{border:1px solid #d7e1dc;border-radius:8px;padding:11px;font:inherit}.quick-options{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-top:14px}.quick-options input{display:none}.quick-options span{display:block;border:1px solid #d7e1dc;border-radius:8px;padding:13px;font-weight:700;color:#24433a}.quick-options input:checked+span{background:#eaf6ef;border-color:#62b48e;color:#0b6e48}.quick-options i{display:none;margin-right:7px}.quick-options input:checked+span i{display:inline}.save-footer{margin-top:25px;border:0;border-radius:8px;background:#126a4b;color:white;padding:12px 18px;font-weight:700;cursor:pointer}.notice{padding:12px;background:#eaf6ef;color:#0b6e48;border-radius:8px}@media(max-width:600px){.quick-options,.social-fields{grid-template-columns:1fr}}</style></head><body><div class="admin-shell"><aside class="sidebar" id="sidebar"><button class="sidebar-close"><i class="ri-close-line"></i></button><a href="{{ url('/') }}" class="brand"><img src="{{ asset('images/web-logo.svg') }}" alt="Indus Resort"><span>ADMIN PANEL</span></a><nav class="menu"><a href="{{ route('admin.login') }}"><i class="ri-home-5-line"></i> Dashboard</a><a href="{{ route('admin.home-settings') }}"><i class="ri-settings-3-line"></i> Home Settings</a><a href="{{ route('admin.rooms') }}"><i class="ri-hotel-bed-line"></i> Rooms &amp; Suites</a><a href="{{ route('admin.gallery') }}"><i class="ri-image-line"></i> Gallery</a><a href="{{ route('admin.messages') }}"><i class="ri-message-3-line"></i> Messages</a><a href="{{ route('admin.contact-settings') }}"><i class="ri-mail-line"></i> Contact Us</a><a href="{{ route('admin.seo-settings') }}"><i class="ri-search-eye-line"></i> SEO Settings</a><a class="active" href="{{ route('admin.footer-settings') }}"><i class="ri-layout-bottom-line"></i> Footer Settings</a></nav><div class="sidebar-footer"><span>Indus Resort &amp; Restaurant</span><span>Admin Panel · v1.0.0</span></div></aside><main class="content"><header class="topbar"><button class="menu-toggle"><i class="ri-menu-line"></i></button></header><div class="page-title"><a href="{{ route('admin.login') }}"><i class="ri-arrow-left-line"></i> Back to Dashboard</a><h1>Footer Settings</h1><p>Manage the text and quick links shown at the bottom of your website.</p></div><section class="panel footer-editor"><h2><i class="ri-layout-bottom-line"></i> Footer Content</h2><p class="muted">Choose exactly what visitors see in the footer.</p>@if(session('success'))<p class="notice">{{ session('success') }}</p>@endif<form method="POST" action="{{ route('admin.footer-settings.update') }}">@csrf<label><b>Footer Description</b><p class="muted">This text appears below the resort logo.</p><textarea name="description" rows="4" required>{{ old('description', $footerSettings['description']) }}</textarea></label><h3>Social Media Links</h3><p class="muted">Paste the full public profile link for each platform.</p><div class="social-fields"><label>Instagram<input type="url" name="instagram" placeholder="https://instagram.com/your-page" value="{{ old('instagram', $footerSettings['instagram'] ?? '') }}"></label><label>Facebook<input type="url" name="facebook" placeholder="https://facebook.com/your-page" value="{{ old('facebook', $footerSettings['facebook'] ?? '') }}"></label><label>WhatsApp<input type="url" name="whatsapp" placeholder="https://wa.me/923000000000" value="{{ old('whatsapp', $footerSettings['whatsapp'] ?? '') }}"></label></div><h3>Quick Links</h3><p class="muted">Tick the pages you want to show in the footer.</p><div class="quick-options">@foreach(['home'=>'Home','about'=>'About','rooms'=>'Rooms & Suites','gallery'=>'Gallery','contact'=>'Contact Us'] as $key=>$label)<label><input type="checkbox" name="quick_links[]" value="{{ $key }}" {{ in_array($key, old('quick_links', $footerSettings['quick_links'])) ? 'checked' : '' }}><span><i class="ri-check-line"></i>{{ $label }}</span></label>@endforeach</div><button class="save-footer" type="submit"><i class="ri-save-line"></i> Save Footer Settings</button></form></section></main></div><script>const sidebar=document.getElementById('sidebar');document.querySelector('.menu-toggle').onclick=()=>sidebar.classList.add('open');document.querySelector('.sidebar-close').onclick=()=>sidebar.classList.remove('open');</script></body></html>
